1	/**
2	 * SubProcessAdapter — ExecutorPort adapter (Wave 3 / T5).
3	 *
4	 * Wave 3 version implements the async runner-callback shape:
5	 *  - submit() registers the handle with the broker, then spawns the runner
6	 *    wrapper (T4) as a detached child. Returns the handle immediately without
7	 *    waiting for the executor to finish.
8	 *  - Completion arrives via HTTP callback: runner POSTs { handle, nonce, result }
9	 *    to the broker's /callback endpoint; the orchestrator drains via
10	 *    broker.listCompleted (T6).
11	 *  - readResult() is a no-op for this profile — result rides in the callback.
12	 *  - ack() removes the handle from the supervision map, cleans up the result
13	 *    file, and delegates to broker.ack.
14	 *
15	 * Runner-supervision map:
16	 *   Keyed by handle; stores (pid, startedAt, nonce, callbackUrl, resultPath).
17	 *   Purpose: the wrapper-crash safety net only — not in-flight state (the
18	 *   broker owns that). On child.on('exit'), a grace timer fires; if the
19	 *   handle is still in the supervision map when the timer fires, the adapter
20	 *   POSTs a synthetic "failed" completion to the broker on the runner's behalf.
21	 */
22	
23	import { spawn } from "node:child_process";
24	import { unlinkSync, rmSync } from "node:fs";
25	import { join } from "node:path";
26	import * as http from "node:http";
27	import * as https from "node:https";
28	import type {
29	  ExecutorPort,
30	  ExecutorPortInput,
31	  ExecutorHandle,
32	  ExecutorResult,
33	  CompletionBrokerPort,
34	  HandleKind,
35	} from "@workflow/runtime-abi";
36	
37	// ── Types ─────────────────────────────────────────────────────────────────────
38	
39	export interface SubProcessAdapterOpts {
40	  /**
41	   * Path to runner.js (the platform-owned wrapper script from T4).
42	   * Defaults to the standard location baked into the container image.
43	   */
44	  runnerBinPath?: string;
45	
46	  /**
47	   * Path to the executor binary. Passed as EXECUTOR_BIN env var to the
48	   * runner wrapper so it knows what to exec. Defaults to the standard
49	   * container location; override in tests.
50	   */
51	  executorBinPath?: string;
52	
53	  /**
54	   * Maximum wall-clock milliseconds before the watchdog kills the runner.
55	   * Defaults to 2 hours (7_200_000 ms).
56	   */
57	  timeoutMs?: number;
58	
59	  /**
60	   * Extra environment variables passed to the runner wrapper (and inherited
61	   * by the executor). Used for single-container extras like
62	   * GIT_AUTHOR_EMAIL, WORKFLOW_LOCAL_PATH, etc.
63	   */
64	  extraEnv?: NodeJS.ProcessEnv;
65	
66	  /**
67	   * Host directory under which per-handle exec dirs live.
68	   * ack() removes `<workspacesDir>/exec-<handle>` after result is processed.
69	   */
70	  workspacesDir?: string;
71	
72	  /**
73	   * CompletionBrokerPort instance. Required for the full async callback flow.
74	   * If absent, broker.register is skipped and the adapter operates in
75	   * broker-less mode (useful for isolated unit tests).
76	   */
77	  broker?: CompletionBrokerPort;
78	
79	  /**
80	   * Grace window (ms) after child.on('exit') before the safety-net synthetic
81	   * failure is posted to the broker. This allows a callback that was in-flight
82	   * at crash time to arrive before we synthesize a failure.
83	   * Default: 5 000 ms.
84	   */
85	  crashGraceMs?: number;
86	
87	  /**
88	   * Handle kind registered with the broker. Defaults to "impl".
89	   * Override to "review" for reviewer executor submissions so the reap loop
90	   * can route completions to dispatchReviewResult instead of dispatchExecutorResult.
91	   */
92	  handleKind?: HandleKind;
93	}
94	
95	interface SupervisionEntry {
96	  pid: number;
97	  startedAt: string; // ISO 8601
98	  nonce: string;
99	  callbackUrl: string;
100	  resultPath: string;
101	  taskId: string;
102	  featureId: string;
103	}
104	
105	// ── Defaults ──────────────────────────────────────────────────────────────────
106	
107	const DEFAULT_RUNNER_BIN = join(
108	  process.env.EXECUTOR_BIN_PREFIX ?? "/workflow",
109	  "runtime",
110	  "runner-wrapper",
111	  "runner.js",
112	);
113	
114	const DEFAULT_TIMEOUT_MS = 7_200_000;
115	const DEFAULT_CRASH_GRACE_MS = 5_000;
116	
117	// ── Helpers ───────────────────────────────────────────────────────────────────
118	
119	function emit(event: Record<string, unknown>): void {
120	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
121	}
122	
123	/** HTTP POST for the safety-net synthetic failure. Resolves regardless of status. */
124	function _httpPost(url: string, body: string): Promise<void> {
125	  return new Promise((resolve, reject) => {
126	    let u: URL;
127	    try {
128	      u = new URL(url);
129	    } catch {
130	      reject(new Error(`_httpPost: invalid URL: ${url}`));
131	      return;
132	    }
133	    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
134	    const req = lib.request(
135	      {
136	        hostname: u.hostname,
137	        port: u.port || (u.protocol === "https:" ? 443 : 80),
138	        path: u.pathname + u.search,
139	        method: "POST",
140	        headers: {
141	          "Content-Type": "application/json",
142	          "Content-Length": Buffer.byteLength(body),
143	        },
144	      },
145	      (res) => {
146	        res.resume(); // drain the response
147	        resolve();
148	      },
149	    );
150	    req.on("error", reject);
151	    req.write(body);
152	    req.end();
153	  });
154	}
155	
156	// ── SubProcessAdapter ─────────────────────────────────────────────────────────
157	
158	export class SubProcessAdapter implements ExecutorPort {
159	  private readonly runnerBinPath: string;
160	  private readonly executorBinPath: string | undefined;
161	  private readonly timeoutMs: number;
162	  private readonly extraEnv: NodeJS.ProcessEnv;
163	  private readonly broker: CompletionBrokerPort | null;
164	  private readonly crashGraceMs: number;
165	  private readonly handleKind: HandleKind;
166	  private readonly workspacesDir: string | undefined;
167	
168	  /** Keyed by handle; tracks in-flight runners for the safety-net sweep. */
169	  private readonly supervision = new Map<ExecutorHandle, SupervisionEntry>();
170	
171	  constructor(opts: SubProcessAdapterOpts = {}) {
172	    this.runnerBinPath = opts.runnerBinPath ?? DEFAULT_RUNNER_BIN;
173	    this.executorBinPath = opts.executorBinPath;
174	    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
175	    this.extraEnv = opts.extraEnv ?? {};
176	    this.broker = opts.broker ?? null;
177	    this.crashGraceMs = opts.crashGraceMs ?? DEFAULT_CRASH_GRACE_MS;
178	    this.handleKind = opts.handleKind ?? "impl";
179	    this.workspacesDir = opts.workspacesDir;
180	  }
181	
182	  // ── ExecutorPort ─────────────────────────────────────────────────────────
183	
184	  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
185	    const {
186	      taskId,
187	      featureId,
188	      workspaceId,
189	      handle,
190	      taskRepoUrl,
191	      taskRepoBranch,
192	      taskBaseBranch,
193	      taskRepoBaseBranch,
194	      executorWorkdir,
195	      mgmtRepoUrl,
196	      resultPath,
197	      budgetTokens,
198	      implementationModel,
199	      sshPrivateKey,
200	      githubToken,
201	      callbackUrl,
202	      nonce,
203	    } = input;
204	    const startedAt = new Date().toISOString();
205	
206	    // 1. Register handle with broker before spawning (broker must record it
207	    //    before the runner can POST back, else the callback arrives at an
208	    //    unregistered handle and is rejected 401).
209	    if (this.broker) {
210	      await this.broker.register(handle, nonce, {
211	        kind: input.kind ?? this.handleKind ?? "impl",
212	        task_id: taskId,
213	        feature_id: featureId,
214	        started_at: startedAt,
215	      });
216	    }
217	
218	    // 2. Build environment for the runner wrapper (and inherited by executor).
219	    const childEnv: NodeJS.ProcessEnv = {
220	      ...process.env,
221	      ...this.extraEnv,
222	      // Formal ABI env vars — passed through to the executor
223	      TASK_ID: taskId,
224	      FEATURE_ID: featureId,
225	      WORKSPACE_ID: workspaceId,
226	      TASK_REPO_URL: taskRepoUrl,
227	      TASK_REPO_BRANCH: taskRepoBranch,
228	      TASK_BASE_BRANCH: taskBaseBranch,
229	      TASK_REPO_BASE_BRANCH: taskRepoBaseBranch,
230	      EXECUTOR_WORKDIR: executorWorkdir,
231	      MGMT_REPO_URL: mgmtRepoUrl,
232	      RESULT_PATH: resultPath,
233	      GITHUB_TOKEN: githubToken,
234	      ...(sshPrivateKey ? { SSH_PRIVATE_KEY: sshPrivateKey } : {}),
235	      ...(budgetTokens !== undefined ? { BUDGET_TOKENS: String(budgetTokens) } : {}),
236	      ...(implementationModel ? { IMPLEMENTATION_MODEL: implementationModel } : {}),
237	      // Runner wrapper contract (T-Q10)
238	      CALLBACK_URL: callbackUrl,
239	      HANDLE: handle,
240	      NONCE: nonce,
241	      ...(this.executorBinPath ? { EXECUTOR_BIN: this.executorBinPath } : {}),
242	    };
243	
244	    emit({
245	      type: "executor_spawn",
246	      task_id: taskId,
247	      feature_id: featureId,
248	      handle,
249	      runner: this.runnerBinPath,
250	    });
251	
252	    // 3. Spawn runner wrapper — non-blocking; returns immediately.
253	    const child = spawn("node", [this.runnerBinPath], {
254	      env: childEnv,
255	      stdio: "inherit",
256	      detached: false,
257	    });
258	
259	    // 4. Track in supervision map.
260	    this.supervision.set(handle, {
261	      pid: child.pid ?? 0,
262	      startedAt,
263	      nonce,
264	      callbackUrl,
265	      resultPath,
266	      taskId,
267	      featureId,
268	    });
269	
270	    // 5. Watchdog: kill runner if it exceeds the wall-clock timeout.
271	    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(() => {
272	      watchdog = null;
273	      if (!child.killed) {
274	        emit({
275	          type: "executor_timeout",
276	          task_id: taskId,
277	          feature_id: featureId,
278	          handle,
279	          timeout_ms: this.timeoutMs,
280	        });
281	        child.kill("SIGTERM");
282	      }
283	    }, this.timeoutMs);
284	    // Don't hold the event loop open for the watchdog.
285	    if (watchdog.unref) watchdog.unref();
286	
287	    // 6. Safety net: if the runner exits without the broker receiving a
288	    //    callback within crashGraceMs, synthesize a "failed" completion.
289	    child.on("exit", (code, signal) => {
290	      if (watchdog !== null) {
291	        clearTimeout(watchdog);
292	        watchdog = null;
293	      }
294	
295	      emit({
296	        type: "executor_exit",
297	        task_id: taskId,
298	        feature_id: featureId,
299	        handle,
300	        exit_code: code,
301	        signal,
302	      });
303	
304	      // Exit code 0 means runner.js completed its postWithRetry successfully —
305	      // the broker already has the real result. Skip the safety net entirely.
306	      // The supervision entry stays so ack() can still clean up the result file.
307	      if (code === 0 && signal === null) {
308	        return;
309	      }
310	
311	      const graceTimer: ReturnType<typeof setTimeout> = setTimeout(() => {
312	        if (!this.supervision.has(handle)) return; // already acked
313	        const entry = this.supervision.get(handle)!;
314	        this.supervision.delete(handle);
315	
316	        if (!entry.callbackUrl) return; // no callback URL to POST to
317	
318	        const reason = signal
319	          ? `runner_killed_by_signal: ${signal}`
320	          : code !== null && code !== 0
321	            ? `runner_crashed (exit ${code})`
322	            : "runner_no_callback";
323	
324	        emit({
325	          type: "executor_safety_net",
326	          task_id: entry.taskId,
327	          feature_id: entry.featureId,
328	          handle,
329	          reason,
330	        });
331	
332	        const body = JSON.stringify({
333	          handle,
334	          nonce: entry.nonce,
335	          result: { terminal_status: "failed", blocked_reason: reason },
336	        });
337	
338	        _httpPost(entry.callbackUrl, body).catch(() => {
339	          // Best-effort — ignore POST failures in the safety net.
340	        });
341	      }, this.crashGraceMs);
342	
343	      // Don't hold the event loop open for the grace timer.
344	      if (graceTimer.unref) graceTimer.unref();
345	    });
346	
347	    return handle;
348	  }
349	
350	  /**
351	   * Wave 3: result arrives via broker callback — readResult is a no-op for
352	   * this profile. Returns a "failed / handle_not_found" tombstone so callers
353	   * that mistakenly poll readResult get a predictable signal.
354	   */
355	  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
356	    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
357	  }
358	
359	  // ── Supervision helpers ───────────────────────────────────────────────────
360	
361	  /**
362	   * Acknowledge a completed handle:
363	   *  - Removes the entry from the supervision map (disarms the safety net).
364	   *  - Deletes the temp result file written by the executor.
365	   *  - Delegates to broker.ack to commit consumption in the broker.
366	   *
367	   * Call this after the orchestrator has successfully processed the completion
368	   * returned by broker.listCompleted.
369	   */
370	  async ack(handle: ExecutorHandle): Promise<void> {
371	    const entry = this.supervision.get(handle);
372	    if (entry) {
373	      this.supervision.delete(handle);
374	      try {
375	        unlinkSync(entry.resultPath);
376	      } catch {
377	        // Best-effort — file may already be gone.
378	      }
379	      if (this.workspacesDir) {
380	        try {
381	          rmSync(join(this.workspacesDir, `exec-${handle}`), { recursive: true, force: true });
382	        } catch {
383	          // Best-effort — dir may not exist (e.g. executor never wrote to it).
384	        }
385	      }
386	    }
387	    if (this.broker) {
388	      await this.broker.ack(handle);
389	    }
390	  }
391	
392	  /** Number of handles currently tracked in the supervision map. */
393	  supervisionSize(): number {
394	    return this.supervision.size;
395	  }
396	}
