    emitWarning({
      type: "model_override_parse_warning",
      taskId,
      reason: "### Model overrides block must be a YAML mapping",
    });
    return {};
  }

  const result: ModelOverrides = {};

  for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {
