      continue;
    }
    if (!isValidPhasePolicy(value)) {
      emitWarning({
        type: "model_override_parse_warning",
        taskId,
        reason: `Phase "${key}" must have allowed (non-empty string array) and default (non-empty string) — skipping`,
      });
      continue;
    }
    result[key as Phase] = value;
  }

  return result;
}
