153	/** HTTP POST — resolves regardless of response status. Rejects on transport error. */
154	function _httpPost(url: string, body: string): Promise<void> {
155	  return new Promise((resolve, reject) => {
156	    let u: URL;
157	    try {
158	      u = new URL(url);
159	    } catch {
160	      reject(new Error(`_httpPost: invalid URL: ${url}`));
161	      return;
162	    }
163	    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
164	    const req = lib.request(
165	      {
166	        hostname: u.hostname,
167	        port: u.port || (u.protocol === "https:" ? 443 : 80),
168	        path: u.pathname + u.search,
169	        method: "POST",
170	        headers: {
171	          "Content-Type": "application/json",
172	          "Content-Length": Buffer.byteLength(body),
173	        },
174	      },
175	      (res) => {
176	        res.resume();
177	        resolve();
178	      },
179	    );
180	    req.on("error", reject);
181	    req.write(body);
182	    req.end();
183	  });
184	}
