403	    if (this.broker) {
404	      await this.broker.ack(handle);
405	    }
406	  }
407	
408	  // ── Supervision helpers ───────────────────────────────────────────────────
409	
410	  /** Number of handles currently tracked in the supervision map. */
411	  supervisionSize(): number {
412	    return this.supervision.size;
413	  }
414	
415	  /** Stop the orphan sweep timer. Call during graceful shutdown. */
416	  stopOrphanSweep(): void {
417	    if (this.orphanSweepTimer) {
418	      clearInterval(this.orphanSweepTimer);
419	      this.orphanSweepTimer = null;
420	    }
421	  }
422	
423	  // ── Internal ─────────────────────────────────────────────────────────────
424	
425	  /**
426	   * Run `docker wait <containerId>` in the background. When the container
427	   * exits, if the handle is still in the supervision map (no callback arrived
428	   * yet), fire a synthetic "failed" completion to the broker after crashGraceMs.
429	   */
430	  private _watchContainer(
431	    handle: ExecutorHandle,
432	    containerId: string,
433	    containerName: string,
434	    callbackUrl: string,
435	    nonce: string,
436	    taskId: string,
437	    featureId: string,
