459	        if (watchdog !== null) {
460	          clearTimeout(watchdog);
461	          watchdog = null;
462	        }
463	
464	        emit({
465	          type: "executor_exit",
466	          task_id: taskId,
467	          feature_id: featureId,
468	          handle,
469	          container_id: containerId,
470	          exit_code: exitCode,
471	        });
472	
473	        // Grace timer before firing safety net.
474	        const graceTimer = setTimeout(() => {
475	          if (!this.supervision.has(handle)) return; // already acked
476	          const entry = this.supervision.get(handle)!;
477	          this.supervision.delete(handle);
478	
479	          const reason =
480	            exitCode !== 0
481	              ? `runner_crashed (exit ${exitCode})`
482	              : "runner_no_callback";
483	
484	          emit({
485	            type: "executor_safety_net",
486	            task_id: entry.taskId,
487	            feature_id: entry.featureId,
488	            handle,
489	            container_id: containerId,
490	            reason,
491	          });
492	
493	          const body = JSON.stringify({
494	            handle,
495	            nonce: entry.nonce,
496	            result: { terminal_status: "failed", blocked_reason: reason },
497	          });
