499	          _httpPost(entry.callbackUrl, body).catch(() => {
500	            // Best-effort — ignore POST failures in the safety net.
501	          });
502	        }, this.crashGraceMs);
503	
504	        if (graceTimer.unref) graceTimer.unref();
505	      })
506	      .catch(() => {
507	        // docker wait failed (container removed before we could wait, etc.).
508	        // The safety net won't fire, but the broker's visibility timeout will
509	        // reclaim the completion eventually.
510	        if (watchdog !== null) {
511	          clearTimeout(watchdog);
512	          watchdog = null;
513	        }
514	      });
515	  }
516	
517	  /**
518	   * Periodic orphan sweep.
519	   *
520	   * Lists all containers with a `platform.handle` label, checks which ones
521	   * are exited and whose handles are NOT in the in-flight supervision map
522	   * (i.e. already acked or never registered), and removes them.
523	   */
524	  private async _orphanSweep(): Promise<void> {
525	    let stdout: string;
526	    try {
527	      const result = await execFileAsync(this.dockerBin, [
528	        "ps", "-a",
529	        "--filter", "label=platform.handle",
530	        "--format", "{{.ID}}\t{{.Label \"platform.handle\"}}\t{{.Status}}",
531	      ]);
532	      stdout = result.stdout;
533	    } catch {
534	      return; // docker unavailable; skip sweep
535	    }
536	
537	    const lines = stdout.trim().split("\n").filter(Boolean);
538	    for (const line of lines) {
539	      const [containerId, handle, status] = line.split("\t");
540	      if (!containerId || !handle || !status) continue;
541	
542	      // Only remove exited containers whose handles are not in supervision.
543	      if (status.toLowerCase().startsWith("exited") && !this.supervision.has(handle)) {
544	        emit({
545	          type: "orphan_container_removed",
546	          container_id: containerId,
547	          handle,
548	        });
549	        execFileAsync(this.dockerBin, ["rm", containerId]).catch(() => {/* best-effort */});
550	      }
551	    }
552	  }
553	}
