/**
 * Executor adapter factory.
 *
 * Two orthogonal env vars control executor selection:
 *   EXECUTOR_PROFILE — infrastructure topology (how the executor is spawned)
 *     "local-subprocess" (default) — fork a child process
 *   EXECUTOR_TYPE — which agent binary runs
 *     "claude" (default) — Claude executor
 *     "hermes"           — Hermes executor
 *
 * Per-task routing (execution.runtime on task YAMLs) is deferred to
 * agent-runtime-selector. Selection here is static at startup.
 */

import * as path from "node:path";
import type { ExecutorPort, CompletionBrokerPort } from "@workflow/runtime-abi";
import { SubProcessAdapter } from "./executor/subprocess.js";

const DEFAULT_BIN_PREFIX = process.env.EXECUTOR_BIN_PREFIX ?? "/workflow";

// ── Config ─────────────────────────────────────────────────────────────────────

export interface ExecutorFactoryConfig {
  /** Path to the compiled Claude executor dist directory (containing index.js). */
  claudeExecutorDist?: string;
  /** Path to the compiled Hermes executor dist directory (containing index.js). */
  hermesExecutorDist?: string;

  /** Hermes inference model ID (e.g. "deepseek-v4-flash"). */
  hermesModel?: string;
  /** Hermes inference provider (e.g. "deepseek"). */
  hermesProvider?: string;
  /** DeepSeek API credential — injected into Hermes executor env. */
  deepseekApiKey?: string;
  /** Optional RAG MCP server URL (written to HERMES_HOME/config.yaml by the executor). */
  ragMcpUrl?: string;
  /** Optional RAG MCP auth token. */
  ragMcpToken?: string;
  /** Optional max tool iterations for Hermes. Defaults to 150 inside the executor. */
  hermesMaxTurns?: number;

  /**
   * Extra environment variables merged into the child env after executor-type
   * env vars. Callers use this for per-task vars (TASK_BRANCH, MAX_TURNS, etc.).
   * Executor-type vars resolved by resolveExecutorEnv take lower precedence — they
   * are applied first; extraEnv can override them.
   */
  extraEnv?: Record<string, string>;

  /** CompletionBrokerPort wired into the adapter for handle registration. */
  broker?: CompletionBrokerPort;

  /** Host directory under which per-handle exec dirs live. */
  workspacesDir?: string;
}

// ── Helpers ────────────────────────────────────────────────────────────────────

/**
 * Resolve the executor binary path for the given executor type.
 *
 * Falls back to the default location under EXECUTOR_BIN_PREFIX when
 * the config does not supply an explicit dist directory.
 */
export function resolveExecutorBin(
  type: string,
  config: ExecutorFactoryConfig,
): string {
  switch (type) {
    case "hermes":
      return path.join(
        config.hermesExecutorDist ??
          path.join(DEFAULT_BIN_PREFIX, "runtime", "executors", "hermes", "dist"),
        "index.js",
      );
    case "claude":
    default:
      return path.join(
        config.claudeExecutorDist ??
          path.join(DEFAULT_BIN_PREFIX, "runtime", "executors", "claude", "dist"),
        "index.js",
      );
  }
}

/**
 * Resolve executor-type-specific environment variables.
 *
 * Hermes requires model/provider credentials injected via env because:
 *   - The orchestrator must stay blind to executor internals.
 *   - Env vars are the version-stable boundary between the two codebases.
 *   - The same interface works for subprocess and future container topologies.
 *
 * Claude currently requires no extra env beyond what the ABI already provides.
 */
export function resolveExecutorEnv(
  type: string,
  config: ExecutorFactoryConfig,
): Record<string, string> {
  switch (type) {
    case "hermes": {
      const env: Record<string, string> = {
        HERMES_INFERENCE_MODEL: config.hermesModel ?? "",
        HERMES_INFERENCE_PROVIDER: config.hermesProvider ?? "",
        DEEPSEEK_API_KEY: config.deepseekApiKey ?? "",
      };
      if (config.ragMcpUrl) env.RAG_MCP_URL = config.ragMcpUrl;
      if (config.ragMcpToken) env.RAG_MCP_TOKEN = config.ragMcpToken;
      if (config.hermesMaxTurns !== undefined) {
        env.HERMES_MAX_TURNS = String(config.hermesMaxTurns);
      }
      return env;
    }
    case "claude":
    default:
      return {};
  }
}

// ── Factory ───────────────────────────────────────────────────────────────────

/**
 * Create an ExecutorPort wired for the active EXECUTOR_PROFILE and EXECUTOR_TYPE.
 *
 * EXECUTOR_PROFILE selects the adapter class (infrastructure topology).
 * EXECUTOR_TYPE    selects the binary path and executor-specific env vars.
 *
 * Adding a new executor type: add a case to resolveExecutorBin / resolveExecutorEnv.
 * Adding a new topology:      add a case to the profile switch below.
 * The two axes never mix.
 */
export function createExecutorAdapter(config: ExecutorFactoryConfig): ExecutorPort {
  const profile = process.env.EXECUTOR_PROFILE ?? "local-subprocess";
  const executorType = process.env.EXECUTOR_TYPE ?? "claude";

  switch (profile) {
    case "local-subprocess":
      return new SubProcessAdapter({
        executorBinPath: resolveExecutorBin(executorType, config),
        extraEnv: {
          ...resolveExecutorEnv(executorType, config),
          ...(config.extraEnv ?? {}),
        },
        broker: config.broker,
        workspacesDir: config.workspacesDir,
      });

    default:
      throw new Error(`Unknown EXECUTOR_PROFILE: ${profile}`);
  }
}

